previewCss:
.darma-loader-darma-b10-rainbow-arc { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b10-rainbow-arc span { position: absolute; inset: 0; margin: auto; border-radius: 50%; border: calc(var(--loader-size, 80px) * .05) solid transparent; box-sizing: border-box; }
.darma-loader-darma-b10-rainbow-arc span:nth-child(1) { border-top-color: var(--accent); animation: darma-loader-darma-b10-rainbow-arc-arc-cw calc(var(--loader-speed, 1s) * 1.2) linear infinite; }
.darma-loader-darma-b10-rainbow-arc span:nth-child(2) { inset: 16%; border-top-color: var(--accent-2); border-right-color: var(--accent-2); animation: darma-loader-darma-b10-rainbow-arc-arc-ccw calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b10-rainbow-arc span:nth-child(3) { inset: 32%; border-top-color: color-mix(in srgb, #fff 35%, var(--accent)); animation: darma-loader-darma-b10-rainbow-arc-arc-cw calc(var(--loader-speed, 1s) * .9) linear infinite; }
.darma-loader-darma-b10-rainbow-arc span:nth-child(4) { inset: 48%; border-top-color: color-mix(in srgb, #fff 35%, var(--accent-2)); border-bottom-color: color-mix(in srgb, #fff 35%, var(--accent-2)); animation: darma-loader-darma-b10-rainbow-arc-arc-ccw calc(var(--loader-speed, 1s) * 1.3) linear infinite; }
@keyframes darma-loader-darma-b10-rainbow-arc-arc-cw { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b10-rainbow-arc-arc-ccw { to { transform: rotate(-360deg); } }

